```
import json

struct User {
    name string
    age  int
mut:
    is_registered bool
}

fn main() {
    s := '[{"name":"Frodo", "age":25}, {"name":"Bobby", "age":10}]'
    mut users := json.decode([]User, s) or {
        eprintln('Failed to parse json')
        return
    }
    for user in users {
        println('${user.name}: ${user.age}')
    }
    println('')
    for i, mut user in users {
        println('${i}) ${user.name}')
        if !user.can_register() {
            println('Cannot register ${user.name}, they are too young')
            continue
        }
		// `user` is declared as `mut` in the for loop,
		// modifying it will modify the array
        user.register()
    }
    // Let's encode users again just for fun
    println('')
    println(json.encode(users))
}

fn (u User) can_register() bool {
    return u.age >= 16
}

fn (mut u User) register() {
    u.is_registered = true
}

```

```
interface Named {
    name string
}

struct User {
    name string
    age  int
}

fn longest[T Named](a T, b T) T {
    return if a.name.len >= b.name.len { a } else { b }
}

type Number = int | f64

fn half[T Number](x T) T {
    return x / 2
}

fn main() {
    println(longest(User{ name: 'ana' }, User{ name: 'leonor' }).name) // leonor
    println(half(7)) // 3
    println(half(1.5)) // 0.75
}
```

